use crate::builder::room;
use crate::memory::{add, bytes};
use crate::types::{invalid, limit, stopped};
use crate::*;
impl SceneBuilder {
    pub fn append_shape(
        &mut self,
        scene: SceneId,
        input: ShapeInput,
        control: &mut dyn WorkControl,
    ) -> Result<ShapeId> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        if input.path.edges.len() != input.edge_colors.len() {
            return Err(invalid(0));
        }
        crate::validate::shape_attributes(self, scene, &input.shape, control)?;
        crate::validate::path(&self.source, &input.path, control)?;
        let s = &self.scenes[i];
        for (len, extra, cap, kind) in [
            (s.shapes.len(), 1, self.limits.shapes, LimitKind::Shapes),
            (
                s.edges.len(),
                input.path.edges.len(),
                self.limits.edges,
                LimitKind::Edges,
            ),
            (
                s.path_segments.len(),
                input.path.segments.len(),
                self.limits.commands,
                LimitKind::PathCommands,
            ),
            (
                s.path_numbers.len(),
                input.path.numbers.len(),
                self.limits.numbers,
                LimitKind::PathNumbers,
            ),
        ] {
            if add(len, extra)? > cap {
                return Err(limit(kind));
            }
        }
        let pending = add(
            add(
                add(bytes(&input.path.edges)?, bytes(&input.path.subpaths)?)?,
                add(bytes(&input.path.segments)?, bytes(&input.path.numbers)?)?,
            )?,
            bytes(&input.edge_colors)?,
        )?;
        self.pending(pending)?;
        let serial = self.serial()?;
        room!(self, i, shapes, 1, self.limits.shapes, pending);
        room!(self, i, shapes_serials, 1, self.limits.shapes, pending);
        room!(
            self,
            i,
            edges,
            input.path.edges.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            edge_colors,
            input.edge_colors.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            edge_shape_ids,
            input.path.edges.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            path_subpaths,
            input.path.subpaths.len(),
            self.limits.commands,
            pending
        );
        room!(
            self,
            i,
            path_segments,
            input.path.segments.len(),
            self.limits.commands,
            pending
        );
        room!(
            self,
            i,
            path_numbers,
            input.path.numbers.len(),
            self.limits.numbers,
            pending
        );
        let mark = self.mark(scene)?;
        let id = ShapeId {
            owner: self.owner,
            scene: scene.slot,
            slot: self.scenes[i].shapes.len() as u32,
            serial,
        };
        let result = self.publish_shape(i, id, input, control);
        if result.is_err() {
            self.rollback(mark)?;
        }
        result.map(|()| id)
    }
    fn publish_shape(
        &mut self,
        i: usize,
        id: ShapeId,
        input: ShapeInput,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let scene = &mut self.scenes[i];
        let edge_first = scene.edges.len();
        let number_first = scene.path_numbers.len();
        let mut shape = input.shape;
        shape.edges = TableRange {
            first: edge_first,
            count: input.path.edges.len(),
        };
        shape.subpaths = TableRange {
            first: scene.path_subpaths.len(),
            count: input.path.subpaths.len(),
        };
        for (edge, color) in input.path.edges.into_iter().zip(input.edge_colors) {
            control.charge(WorkKind::Edge, 1).map_err(stopped)?;
            scene.edges.push(edge);
            scene.edge_colors.push(color);
            scene.edge_shape_ids.push(id.slot);
        }
        for mut subpath in input.path.subpaths {
            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
            subpath.first_edge = add(subpath.first_edge, edge_first)?;
            scene.path_subpaths.push(subpath);
        }
        for mut path in input.path.segments {
            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
            path.first_edge = add(path.first_edge, edge_first)?;
            path.first_number = add(path.first_number, number_first)?;
            scene
                .path_segments
                .push(ScenePathSegment { path, shape: id });
        }
        for number in input.path.numbers {
            control.charge(WorkKind::SourceRead, 1).map_err(stopped)?;
            scene.path_numbers.push(number);
        }
        control.checkpoint().map_err(stopped)?;
        scene.shapes.push(shape);
        scene.shapes_serials.push(id.serial);
        Ok(())
    }
}
use crate::{Diagnostic, ErrorKind, LimitKind, Result};
/// Vec-reported reserved storage, excluding allocator bookkeeping and RSS.
/// Allocation history describes builder reserves and admitted owned payloads;
/// it does not reconstruct allocation calls made by parsers/providers before admission.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct MemoryStats {
    pub source_bytes: usize,
    pub live_bytes: usize,
    pub peak_live_bytes: usize,
    pub total_allocated_bytes: usize,
    pub allocation_count: usize,
}
pub(crate) fn bytes<T>(values: &Vec<T>) -> Result<usize> {
    values
        .capacity()
        .checked_mul(std::mem::size_of::<T>())
        .ok_or_else(arithmetic)
}
pub(crate) fn add(a: usize, b: usize) -> Result<usize> {
    a.checked_add(b).ok_or_else(arithmetic)
}
pub(crate) fn arithmetic() -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::Limit(LimitKind::Arithmetic),
        offset: 0,
    }
}
/// Reserve a replacement before transferring old values. Reject excess actual
/// capacity before moving anything. The caller supplies the available overlap budget.
pub(crate) fn reserve<T>(
    values: &mut Vec<T>,
    extra: usize,
    cap: usize,
    overlap: usize,
) -> Result<(usize, usize)> {
    let required = values.len().checked_add(extra).ok_or_else(arithmetic)?;
    if required > cap {
        return Err(Diagnostic {
            kind: ErrorKind::Limit(LimitKind::Nodes),
            offset: 0,
        });
    }
    if required <= values.capacity() {
        return Ok((0, 0));
    }
    let request = required
        .checked_mul(std::mem::size_of::<T>())
        .ok_or_else(arithmetic)?;
    if request > overlap {
        return Err(Diagnostic {
            kind: ErrorKind::Limit(LimitKind::ReservedBytes),
            offset: 0,
        });
    }
    let mut replacement = Vec::new();
    let grown = values
        .capacity()
        .checked_mul(2)
        .unwrap_or(cap)
        .max(8)
        .min(cap)
        .max(required);
    let target = if grown
        .checked_mul(std::mem::size_of::<T>())
        .is_some_and(|n| n <= overlap)
    {
        grown
    } else {
        required
    };
    replacement
        .try_reserve_exact(target)
        .map_err(|_| Diagnostic {
            kind: ErrorKind::OutOfMemory,
            offset: 0,
        })?;
    let actual = bytes(&replacement)?;
    if actual > overlap {
        return Err(Diagnostic {
            kind: ErrorKind::Limit(LimitKind::ReservedBytes),
            offset: 0,
        });
    }
    let old = bytes(values)?;
    replacement.append(values);
    *values = replacement;
    Ok((actual, old))
}
