 93	pub(crate) fn paint(
 94	    builder: &SceneBuilder,
 95	    id: SceneId,
 96	    value: &Paint,
 97	    control: &mut dyn WorkControl,
 98	) -> Result<()> {
 99	    charge(control, WorkKind::PaintVisit)?;
100	    let scene = builder.scene(id)?;
101	    value.stops.require(scene.stops.len(), 0)?;
102	    if value.stops.count > 256 {
103	        return Err(limit(LimitKind::PaintStops));
104	    }
105	    stops(
106	        value.stops.slice(scene.stops).ok_or_else(|| invalid(0))?,
107	        control,
108	    )?;
109	    if !finite(&value.coordinates)
110	        || !region(&value.bounds)
111	        || ![
112	            value.user_inverse,
113	            value.gradient_inverse,
114	            value.pattern_inverse,
115	        ]
116	        .into_iter()
117	        .all(affine_valid)
118	        || !value.pattern_opacity.is_finite()
119	        || !(0.0..=1.0).contains(&value.pattern_opacity)
120	    {
121	        return Err(invalid(0));
122	    }
123	    if value.coordinates.iter().any(|v| v.abs() > 1e6) {
124	        return Err(invalid(0));
125	    }
126	    if value.kind == PaintKind::Radial && value.coordinates[2] < 0.0 {
127	        return Err(invalid(0));
128	    }
129	    if let Some(pattern) = value.pattern {
130	        if scene.pattern(pattern).is_none() {
131	            return Err(invalid(0));
132	        }
133	    }
134	    if value.kind == PaintKind::Pattern && value.pattern.is_none() {
135	        return Err(invalid(0));
136	    }
137	    Ok(())
138	}
139	pub(crate) fn shape_attributes(
140	    builder: &SceneBuilder,
141	    id: SceneId,
142	    value: &Shape,
143	    control: &mut dyn WorkControl,
144	) -> Result<()> {
145	    charge(control, WorkKind::TokenVisit)?;
146	    span(&builder.source, value.source.element)?;
147	    let scene = builder.scene(id)?;
148	    if !affine_valid(value.source.transform) || !affine_valid(value.stroke_inverse) {
149	        return Err(invalid(value.source.element.start));
150	    }
151	    if let Some(node) = value.source.transform_node {
152	        if scene.transform(node).is_none() {
153	            return Err(invalid(0));
154	        }
155	    }
156	    if let Some(clip) = value.clip {
157	        if scene.clip(clip).is_none() {
158	            return Err(invalid(0));
159	        }
160	    }
161	    for (index, length) in [
162	        (value.fill_paint, scene.fill_paints.len()),
163	        (value.stroke_paint, scene.stroke_paints.len()),
164	        (value.image, scene.images.len()),
165	    ] {
166	        if index.is_some_and(|i| i >= length) {
167	            return Err(invalid(0));
168	        }
169	    }
170	    let stroke = value.stroke;
171	    if !stroke.width.is_finite()
172	        || !(0.0..=1024.0).contains(&stroke.width)
173	        || !stroke.miter_limit.is_finite()
174	        || !(1.0..=64.0).contains(&stroke.miter_limit)
175	        || !coord(stroke.dash_offset)
176	        || stroke.paint_order > 5
177	    {
178	        return Err(invalid(0));
179	    }
180	    stroke.dash_values.require(scene.dash_values.len(), 0)?;
181	    if stroke.dash_values.count > 16 {
182	        return Err(limit(LimitKind::DashCache));
183	    }
184	    Ok(())
185	}
186	pub(crate) fn path(
187	    source: &[u8],
188	    value: &vexel_svg_path::PathDocument,
189	    control: &mut dyn WorkControl,
190	) -> Result<()> {
191	    for &e in &value.edges {
192	        charge(control, WorkKind::Edge)?;
193	        edge(e)?;
194	    }
195	    let mut end = 0;
196	    for subpath in &value.subpaths {
197	        charge(control, WorkKind::TokenVisit)?;
198	        let range = TableRange {
199	            first: subpath.first_edge,
200	            count: subpath.edge_count,
201	        };
202	        range.require(value.edges.len(), 0)?;
203	        if range.first < end {
204	            return Err(invalid(0));
205	        }
206	        end = range.end().ok_or_else(|| invalid(0))?;
207	    }
208	    for segment in &value.segments {
209	        charge(control, WorkKind::TokenVisit)?;
210	        segment_valid(source, *segment, value.edges.len(), value.numbers.len())?;
211	    }
212	    for number in &value.numbers {
213	        charge(control, WorkKind::SourceRead)?;
214	        span(source, number.source)?;
215	        if !number.value.is_finite() {
216	            return Err(invalid(number.source.start));
217	        }
218	    }
219	    Ok(())
220	}
221	fn segment_valid(
222	    source: &[u8],
223	    value: vexel_svg_path::PathSegment,
224	    edges: usize,
225	    numbers: usize,
226	) -> Result<()> {
227	    span(source, value.source)?;
228	    TableRange {
229	        first: value.first_edge,
230	        count: value.edge_count,
231	    }
232	    .require(edges, value.source.start)?;
233	    TableRange {
234	        first: value.first_number,
235	        count: value.number_count,
236	    }
237	    .require(numbers, value.source.start)?;
238	    let count = match value.command.to_ascii_uppercase() {
239	        b'M' | b'L' | b'T' => 2,
240	        b'H' | b'V' => 1,
241	        b'C' => 6,
242	        b'S' | b'Q' => 4,
243	        b'A' => 7,
244	        b'Z' => 0,
245	        _ => return Err(invalid(value.source.start)),
246	    };
247	    if value.number_count != count {
248	        return Err(invalid(value.source.start));
249	    }
250	    if let Some(offset) = value.command_offset {
251	        if offset < value.source.start
252	            || offset >= value.source.end
253	            || source.get(offset).map(u8::to_ascii_uppercase)
254	                != Some(value.command.to_ascii_uppercase())
255	        {
256	            return Err(invalid(offset));
257	        }
258	    }
259	    Ok(())
260	}
261	pub(crate) fn image(value: &Image, control: &mut dyn WorkControl) -> Result<()> {
262	    charge(control, WorkKind::Media)?;
263	    value.pixels.validate(0)?;
264	    if value.pixels.width > 16384
265	        || value.pixels.height > 16384
266	        || (value.pixels.width as usize) * (value.pixels.height as usize) > 67_108_864
267	    {
268	        return Err(limit(LimitKind::Images));
269	    }
270	    for row in value.pixels.rgba[..value.pixels.byte_count].chunks_exact(value.pixels.row_stride) {
271	        for pixel in row[..value.pixels.width as usize * 4].chunks_exact(4) {
272	            charge(control, WorkKind::Media)?;
273	            if pixel[..3].iter().any(|v| *v > pixel[3]) {
274	                return Err(invalid(0));
275	            }
276	        }
277	    }
278	    if ![
279	        value.x,
280	        value.y,
281	        value.width,
282	        value.height,
283	        value.draw_x,
284	        value.draw_y,
285	        value.draw_width,
286	        value.draw_height,
287	    ]
288	    .into_iter()
289	    .all(coord)
290	        || value.width <= 0.0
291	        || value.height <= 0.0
292	        || value.draw_width < 0.0
293	        || value.draw_height < 0.0
294	    {
295	        return Err(invalid(0));
296	    }
297	    Ok(())
298	}
299	pub(crate) fn clip(
300	    builder: &SceneBuilder,
301	    id: SceneId,
302	    value: &Clip,
303	    control: &mut dyn WorkControl,
304	) -> Result<()> {
305	    let scene = builder.scene(id)?;
306	    if !region(&value.bounds) || !affine_valid(value.user_inverse) {
307	        return Err(invalid(0));
308	    }
309	    if value.geometry.edges.len() > 65536 || value.geometry.shapes.len() > 64 {
310	        return Err(limit(LimitKind::Clips));
311	    }
312	    if let Some(node) = value.owner_node {
313	        if scene.transform(node).is_none() {
314	            return Err(invalid(0));
315	        }
316	    }
317	    let mut parent = value.parent;
318	    let mut depth = 1;
319	    while let Some(id) = parent {
320	        charge(control, WorkKind::ClipChain)?;
321	        let clip = scene.clip(id).ok_or_else(|| invalid(0))?;
322	        parent = clip.parent;
323	        depth += 1;
324	        if depth > 256 {
325	            return Err(limit(LimitKind::Clips));
326	        }
327	    }
328	    for &e in &value.geometry.edges {
329	        charge(control, WorkKind::ClipEdge)?;
330	        edge(e)?;
331	    }
332	    for child in &value.geometry.shapes {
333	        charge(control, WorkKind::ClipChild)?;
334	        child.edges.require(value.geometry.edges.len(), 0)?;
335	    }
336	    Ok(())
337	}
338	pub(crate) fn pattern(
339	    _builder: &SceneBuilder,
340	    _id: SceneId,
341	    value: &Pattern,
342	    control: &mut dyn WorkControl,
343	) -> Result<()> {
344	    charge(control, WorkKind::PaintVisit)?;
345	    if (value.tile.width() as usize) * (value.tile.height() as usize) > 1_048_576
346	        || value.tile.allocated_byte_count() > 16 * 1024 * 1024
347	    {
348	        return Err(limit(LimitKind::Patterns));
349	    }
350	    if !coord(value.tile_width)
351	        || !coord(value.tile_height)
352	        || value.tile_width <= 0.0
353	        || value.tile_height <= 0.0
354	        || !affine_valid(value.content_transform)
355	    {
356	        return Err(invalid(0));
357	    }
358	    Ok(())
359	}
360	pub(crate) fn mask(
361	    builder: &SceneBuilder,
362	    id: SceneId,
363	    value: &Mask,
364	    control: &mut dyn WorkControl,
365	) -> Result<()> {
