377	pub(crate) fn filter(
378	    value: Filter,
379	    primitives: &[FilterPrimitive],
380	    control: &mut dyn WorkControl,
381	) -> Result<()> {
382	    if primitives.len() > 16 {
383	        return Err(limit(LimitKind::Filters));
384	    }
385	    if !region(&value.region) {
386	        return Err(invalid(0));
387	    }
388	    for (index, p) in primitives.iter().enumerate() {
389	        charge(control, WorkKind::FilterPixel)?;
390	        if p.merge_count > 8 || !finite(&p.values) {
391	            return Err(invalid(p.source_offset));
392	        }
393	        for input in [p.input, p.input2]
394	            .into_iter()
395	            .chain(p.merge_inputs[..p.merge_count as usize].iter().copied())
396	        {
397	            if let FilterInput::Result(result) = input {
398	                if result >= index {
399	                    return Err(invalid(p.source_offset));
400	                }
401	            }
402	        }
403	        let mode_cap = match p.kind {
404	            FilterKind::Blend => 4,
405	            FilterKind::Composite => 6,
406	            FilterKind::ColorMatrix => 3,
407	            _ => 0,
408	        };
409	        if p.mode > mode_cap {
410	            return Err(invalid(p.source_offset));
411	        }
412	        if matches!(p.kind, FilterKind::Offset | FilterKind::DropShadow)
413	            && (p.values[2].abs() > 4096.0 || p.values[3].abs() > 4096.0)
414	        {
415	            return Err(invalid(p.source_offset));
416	        }
417	        if p.kind == FilterKind::ColorMatrix && p.mode == 1 && !(0.0..=1.0).contains(&p.values[0]) {
418	            return Err(invalid(p.source_offset));
419	        }
420	        if matches!(p.kind, FilterKind::GaussianBlur | FilterKind::DropShadow)
421	            && (!(0.0..=32.0).contains(&p.values[0]) || !(0.0..=32.0).contains(&p.values[1]))
422	        {
423	            return Err(invalid(p.source_offset));
424	        }
425	    }
426	    Ok(())
427	}
428	pub(crate) fn group(
429	    builder: &SceneBuilder,
