465	pub(crate) fn scene(
466	    builder: &SceneBuilder,
467	    id: SceneId,
468	    control: &mut dyn WorkControl,
469	) -> Result<()> {
470	    control.checkpoint().map_err(stopped)?;
471	    let i = builder.index(id)?;
472	    let data = &builder.scenes[i];
473	    let view = data.view(builder.owner, i);
474	    viewport(view.viewport)?;
475	    if view.edges.len() != view.edge_colors.len() || view.edges.len() != view.edge_shape_ids.len() {
476	        return Err(invalid(0));
477	    }
478	    for (records, serials) in [
479	        (data.shapes.len(), data.shapes_serials.len()),
480	        (data.transforms.len(), data.transforms_serials.len()),
481	        (data.clips.len(), data.clips_serials.len()),
482	        (data.patterns.len(), data.patterns_serials.len()),
483	        (data.masks.len(), data.masks_serials.len()),
484	        (data.filters.len(), data.filters_serials.len()),
485	        (data.groups.len(), data.groups_serials.len()),
486	    ] {
487	        if records != serials {
488	            return Err(invalid(0));
489	        }
490	    }
491	    for (index, &e) in view.edges.iter().enumerate() {
492	        charge(control, WorkKind::Edge)?;
493	        edge(e)?;
494	        let shape = view
495	            .edge_shape(index)
496	            .and_then(|id| view.shape(id))
497	            .ok_or_else(|| invalid(0))?;
498	        if index < shape.edges.first || index >= shape.edges.end().ok_or_else(|| invalid(0))? {
499	            return Err(invalid(0));
500	        }
501	    }
502	    for shape in view.shapes {
503	        shape_attributes(builder, id, shape, control)?;
504	        shape.edges.require(view.edges.len(), 0)?;
505	        shape.subpaths.require(view.path_subpaths.len(), 0)?;
506	        let mut end = shape.edges.first;
507	        for subpath in shape
508	            .subpaths
509	            .slice(view.path_subpaths)
510	            .ok_or_else(|| invalid(0))?
511	        {
512	            charge(control, WorkKind::TokenVisit)?;
513	            let range = TableRange {
514	                first: subpath.first_edge,
515	                count: subpath.edge_count,
516	            };
517	            range.require(view.edges.len(), 0)?;
518	            if range.first < end || range.end() > shape.edges.end() {
519	                return Err(invalid(0));
520	            }
521	            end = range.end().ok_or_else(|| invalid(0))?;
522	        }
523	    }
524	    for segment in view.path_segments {
525	        charge(control, WorkKind::TokenVisit)?;
526	        segment_valid(
527	            &builder.source,
528	            segment.path,
529	            view.edges.len(),
530	            view.path_numbers.len(),
531	        )?;
532	        let shape = view.shape(segment.shape).ok_or_else(|| invalid(0))?;
533	        let range = TableRange {
534	            first: segment.path.first_edge,
535	            count: segment.path.edge_count,
536	        };
537	        if range.first < shape.edges.first || range.end() > shape.edges.end() {
538	            return Err(invalid(0));
539	        }
540	    }
541	    for number in view.path_numbers {
542	        charge(control, WorkKind::SourceRead)?;
543	        span(&builder.source, number.source)?;
544	        if !number.value.is_finite() {
545	            return Err(invalid(number.source.start));
546	        }
547	    }
548	    for (index, value) in view.transforms.iter().enumerate() {
549	        transform(builder, id, value, control)?;
550	        if value.parent.is_some_and(|p| p.index() >= index) {
551	            return Err(invalid(value.source_offset));
552	        }
553	    }
554	    let mut pixels = 0usize;
555	    for value in view.images {
556	        image(value, control)?;
557	        pixels = crate::memory::add(
558	            pixels,
559	            (value.pixels.width as usize) * (value.pixels.height as usize),
560	        )?;
561	        if pixels > 67_108_864 {
562	            return Err(limit(LimitKind::Images));
563	        }
564	    }
565	    if pixels != data.image_pixels {
566	        return Err(invalid(0));
567	    }
568	    for (index, value) in view.clips.iter().enumerate() {
569	        clip(builder, id, value, control)?;
570	        if value.parent.is_some_and(|p| p.index() >= index) {
571	            return Err(invalid(0));
572	        }
573	    }
574	    for value in view.patterns {
575	        pattern(builder, id, value, control)?;
576	    }
577	    for value in view.masks {
578	        mask(builder, id, value, control)?;
579	    }
580	    for value in view.fill_paints.iter().chain(view.stroke_paints) {
581	        paint(builder, id, value, control)?;
582	    }
583	    for value in view.filters {
584	        charge(control, WorkKind::FilterPixel)?;
585	        value.primitives.require(view.filter_primitives.len(), 0)?;
586	        let primitives = value
587	            .primitives
588	            .slice(view.filter_primitives)
589	            .ok_or_else(|| invalid(0))?;
590	        filter(*value, primitives, control)?;
591	        for primitive in primitives {
592	            charge(control, WorkKind::SourceRead)?;
593	            source_offset(&builder.source, primitive.source_offset)?;
594	        }
595	    }
596	    for (index, value) in view.groups.iter().enumerate() {
597	        group(builder, id, value, control)?;
598	        if value.parent.is_some_and(|p| p.index() >= index) {
599	            return Err(invalid(0));
600	        }
601	    }
602	    for value in view.dash_values {
603	        charge(control, WorkKind::StrokeTest)?;
604	        if !coord(*value) || *value < 0.0 {
605	            return Err(invalid(0));
606	        }
607	    }
608	    // Unreferenced stops and primitives are still retained user input and must validate.
609	    for value in view.stops {
610	        charge(control, WorkKind::PaintVisit)?;
611	        if !value.offset.is_finite() || !(0.0..=1.0).contains(&value.offset) {
612	            return Err(invalid(0));
613	        }
614	    }
615	    Ok(())
616	}

