 38	macro_rules! room {
 39	    ($self:ident,$index:expr,$field:ident,$extra:expr,$cap:expr,$pending:expr) => {{
 40	        let pending = $pending;
 41	        let current = add($self.stats.live_bytes, pending)?;
 42	        let available = $self
 43	            .limits
 44	            .reserved_bytes
 45	            .checked_sub(current)
 46	            .ok_or_else(|| limit(LimitKind::ReservedBytes))?;
 47	        // Check all counters before the mutating reserve can transfer old values.
 48	        let history_room = usize::MAX - $self.stats.total_allocated_bytes;
 49	        let available = available.min(history_room);
 50	        if $self.stats.allocation_count == usize::MAX {
 51	            return Err(arithmetic());
 52	        }
 53	        let (new, old) = reserve(&mut $self.scenes[$index].$field, $extra, $cap, available)?;
 54	        if new != 0 {
 55	            $self.stats.peak_live_bytes = $self.stats.peak_live_bytes.max(add(current, new)?);
 56	            $self.stats.total_allocated_bytes = add($self.stats.total_allocated_bytes, new)?;
 57	            $self.stats.allocation_count += 1;
 58	            $self.stats.live_bytes = add($self.stats.live_bytes - old, new)?;
 59	        }
 60	    }};
 61	}
