 64	impl SceneBuilder {
 65	    pub fn new(
 66	        source: SourceOwner,
 67	        animation: OwnedAnimation,
 68	        generation: u64,
 69	        viewport: Viewport,
 70	        limits: Limits,
 71	    ) -> Result<Self> {
 72	        let limits = limits.effective();
 73	        if !std::sync::Arc::ptr_eq(&source, animation.source_owner()) {
 74	            return Err(invalid(0));
 75	        }
 76	        if source.len() > limits.source_bytes {
 77	            return Err(limit(LimitKind::SourceBytes));
 78	        }
 79	        crate::validate::viewport(viewport)?;
 80	        let live = animation.storage_bytes().ok_or_else(arithmetic)?;
 81	        if live > limits.reserved_bytes {
 82	            return Err(limit(LimitKind::ReservedBytes));
 83	        }
 84	        let owner = NEXT_OWNER
 85	            .try_update(Ordering::Relaxed, Ordering::Relaxed, |v| v.checked_add(1))
 86	            .map_err(|_| arithmetic())?;
 87	        let root = SceneId {
 88	            owner,
 89	            slot: 0,
 90	            serial: 1,
 91	        };
 92	        let mut value = Self {
 93	            owner,
 94	            source,
 95	            generation,
 96	            scenes: Vec::new(),
 97	            animation,
 98	            ignored: [Ignored::default(); 4],
 99	            stats: MemoryStats {
100	                source_bytes: live,
101	                live_bytes: live,
102	                peak_live_bytes: live,
103	                total_allocated_bytes: 0,
104	                allocation_count: 0,
105	            },
106	            limits,
107	            next_serial: 1,
108	            root,
109	        };
110	        value.stats.source_bytes = value.source.capacity();
111	        let actual = value.reserve_scene()?;
112	        value.scenes.push(SceneData::new(actual.serial, viewport));
113	        value.root = actual;
114	        Ok(value)
115	    }
116	    fn reserve_scene(&mut self) -> Result<SceneId> {
117	        let serial = self.serial()?;
118	        let available = self
119	            .limits
120	            .reserved_bytes
121	            .checked_sub(self.stats.live_bytes)
122	            .ok_or_else(|| limit(LimitKind::ReservedBytes))?;
123	        if self.stats.allocation_count == usize::MAX {
124	            return Err(arithmetic());
125	        }
126	        let (new, old) = reserve(
127	            &mut self.scenes,
128	            1,
129	            self.limits.scenes,
130	            available.min(usize::MAX - self.stats.total_allocated_bytes),
131	        )?;
132	        if new != 0 {
133	            self.stats.peak_live_bytes = self
134	                .stats
135	                .peak_live_bytes
136	                .max(add(self.stats.live_bytes, new)?);
137	            self.stats.live_bytes = add(self.stats.live_bytes - old, new)?;
138	            self.stats.total_allocated_bytes = add(self.stats.total_allocated_bytes, new)?;
139	            self.stats.allocation_count += 1;
140	        }
141	        Ok(SceneId {
142	            owner: self.owner,
143	            slot: self.scenes.len() as u32,
144	            serial,
145	        })
146	    }
147	    pub(crate) fn serial(&mut self) -> Result<u64> {
148	        let serial = self.next_serial;
149	        self.next_serial = self.next_serial.checked_add(1).ok_or_else(arithmetic)?;
150	        Ok(serial)
151	    }
152	    pub(crate) fn index(&self, id: SceneId) -> Result<usize> {
153	        let scene = self.scenes.get(id.index()).ok_or_else(|| invalid(0))?;
154	        if id.owner != self.owner || id.serial != scene.serial {
155	            return Err(invalid(0));
156	        }
157	        Ok(id.index())
158	    }
159	    pub(crate) fn writable(&self, id: SceneId) -> Result<usize> {
160	        let index = self.index(id)?;
161	        if self.scenes[index].sealed {
162	            return Err(invalid(0));
163	        }
164	        Ok(index)
165	    }
166	    pub fn root_id(&self) -> SceneId {
167	        self.root
168	    }
169	    pub fn scene(&self, id: SceneId) -> Result<SceneView<'_>> {
170	        let i = self.index(id)?;
171	        Ok(self.scenes[i].view(self.owner, i))
172	    }
173	    pub fn memory_stats(&self) -> MemoryStats {
174	        self.stats
175	    }
176	    pub fn new_scene(&mut self, viewport: Viewport) -> Result<SceneId> {
177	        crate::validate::viewport(viewport)?;
178	        let id = self.reserve_scene()?;
179	        self.scenes.push(SceneData::new(id.serial, viewport));
180	        Ok(id)
181	    }
182	    pub fn mark(&self, scene: SceneId) -> Result<BuildMark> {
183	        let i = self.writable(scene)?;
184	        Ok(BuildMark {
185	            scene,
186	            epoch: self.scenes[i].epoch,
187	            image_pixels: self.scenes[i].image_pixels,
188	            lengths: self.scenes[i].lengths(),
189	        })
190	    }
191	    pub fn rollback(&mut self, mark: BuildMark) -> Result<()> {
192	        let i = self.writable(mark.scene)?;
193	        let scene = &self.scenes[i];
194	        if scene.epoch != mark.epoch
195	            || scene
196	                .lengths()
197	                .iter()
198	                .zip(mark.lengths)
199	                .any(|(now, then)| *now < then)
200	        {
201	            return Err(invalid(0));
202	        }
203	        let epoch = scene.epoch.checked_add(1).ok_or_else(arithmetic)?;
204	        let before = scene.storage_bytes()?;
205	        self.scenes[i].truncate(mark.lengths);
206	        self.scenes[i].epoch = epoch;
207	        self.scenes[i].image_pixels = mark.image_pixels;
208	        let after = self.scenes[i].storage_bytes()?;
209	        self.stats.live_bytes = self.stats.live_bytes - (before - after);
210	        Ok(())
211	    }
212	    /// Seal children before linking them from masks. No mutable child can escape.
213	    pub fn seal(&mut self, id: SceneId, control: &mut dyn WorkControl) -> Result<()> {
214	        let i = self.writable(id)?;
215	        crate::validate::scene(self, id, control)?;
216	        self.scenes[i].sealed = true;
217	        Ok(())
218	    }
219	    pub fn freeze(self) -> Result<SceneGraph> {
220	        self.freeze_controlled(&mut NoStop)
221	    }
222	    pub fn freeze_controlled(mut self, control: &mut dyn WorkControl) -> Result<SceneGraph> {
223	        control.checkpoint().map_err(stopped)?;
224	        for i in 0..self.scenes.len() {
225	            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
226	            let id = SceneId {
227	                owner: self.owner,
228	                slot: i as u32,
229	                serial: self.scenes[i].serial,
230	            };
231	            crate::validate::scene(&self, id, control)?;
232	            self.scenes[i].sealed = true;
233	        }
234	        let mut measured = add(
235	            self.animation.storage_bytes().ok_or_else(arithmetic)?,
236	            bytes(&self.scenes)?,
237	        )?;
238	        for scene in &self.scenes {
239	            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
240	            measured = add(measured, scene.storage_bytes_controlled(control)?)?;
241	        }
242	        if measured != self.stats.live_bytes || measured > self.limits.reserved_bytes {
243	            return Err(invalid(0));
244	        }
245	        Ok(SceneGraph {
246	            owner: self.owner,
247	            source: self.source,
248	            generation: self.generation,
249	            root: self.root,
250	            scenes: self.scenes,
251	            animation: self.animation,
252	            ignored: self.ignored,
253	            stats: self.stats,
254	        })
255	    }
256	    pub fn record_ignored(&mut self, kind: IgnoredKind, offset: usize) -> Result<()> {
257	        if offset > self.source.len() {
258	            return Err(invalid(offset));
259	        }
260	        let record = &mut self.ignored[kind as usize];
261	        record.count = record.count.checked_add(1).ok_or_else(arithmetic)?;
262	        if record.first_offset.is_none() {
263	            record.first_offset = Some(offset);
264	        }
265	        Ok(())
266	    }
267	    pub(crate) fn pending(&mut self, bytes: usize) -> Result<()> {
268	        let total = add(self.stats.live_bytes, bytes)?;
269	        if total > self.limits.reserved_bytes {
270	            return Err(limit(LimitKind::ReservedBytes));
271	        }
272	        self.stats.peak_live_bytes = self.stats.peak_live_bytes.max(total);
273	        Ok(())
274	    }
275	    pub(crate) fn retain(&mut self, bytes: usize) -> Result<()> {
276	        // All arithmetic and budget checks must precede any table publication.
277	        let live = add(self.stats.live_bytes, bytes)?;
278	        let total = add(self.stats.total_allocated_bytes, bytes)?;
279	        let count = self
280	            .stats
281	            .allocation_count
282	            .checked_add(usize::from(bytes != 0))
283	            .ok_or_else(arithmetic)?;
284	        if live > self.limits.reserved_bytes {
285	            return Err(limit(LimitKind::ReservedBytes));
286	        }
287	        self.stats.live_bytes = live;
288	        self.stats.total_allocated_bytes = total;
289	        self.stats.allocation_count = count;
290	        Ok(())
291	    }
292	}
