  2	/// Vec-reported reserved storage, excluding allocator bookkeeping and RSS.
  3	/// Allocation history describes builder reserves and admitted owned payloads;
  4	/// it does not reconstruct allocation calls made by parsers/providers before admission.
  5	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
  6	pub struct MemoryStats {
  7	    pub source_bytes: usize,
  8	    pub live_bytes: usize,
  9	    pub peak_live_bytes: usize,
 10	    pub total_allocated_bytes: usize,
