 27	            self.limits.transforms,
 28	            nested
 29	        );
 30	        control.checkpoint().map_err(stopped)?;
 31	        self.retain(nested)?;
 32	        let id = TransformId {
 33	            owner: self.owner,
 34	            scene: scene.slot,
 35	            slot: self.scenes[i].transforms.len() as u32,
