135	    pub(crate) fn storage_bytes_controlled(&self, control: &mut dyn WorkControl) -> Result<usize> {
136	        let mut total = 0;
137	        total = add(total, bytes(&self.edges)?)?;
138	        total = add(total, bytes(&self.edge_colors)?)?;
139	        total = add(total, bytes(&self.edge_shape_ids)?)?;
140	        total = add(total, bytes(&self.shapes)?)?;
