143	        total = add(total, bytes(&self.path_numbers)?)?;
144	        total = add(total, bytes(&self.transforms)?)?;
145	        total = add(total, bytes(&self.images)?)?;
146	        total = add(total, bytes(&self.groups)?)?;
147	        total = add(total, bytes(&self.filters)?)?;
