153	        total = add(total, bytes(&self.dash_values)?)?;
154	        total = add(total, bytes(&self.stops)?)?;
155	        total = add(total, bytes(&self.clips)?)?;
156	        total = add(total, bytes(&self.shapes_serials)?)?;
157	        total = add(total, bytes(&self.transforms_serials)?)?;
158	        total = add(total, bytes(&self.clips_serials)?)?;
159	        total = add(total, bytes(&self.patterns_serials)?)?;
160	        total = add(total, bytes(&self.masks_serials)?)?;
161	        total = add(total, bytes(&self.filters_serials)?)?;
162	        total = add(total, bytes(&self.groups_serials)?)?;
163	        for image in &self.images {
164	            control
165	                .charge(WorkKind::Media, 1)
166	                .map_err(crate::types::stopped)?;
167	            total = add(total, bytes(&image.pixels.rgba)?)?;
168	        }
169	        for clip in &self.clips {
170	            control
171	                .charge(WorkKind::ClipChild, 1)
172	                .map_err(crate::types::stopped)?;
173	            total = add(
174	                total,
175	                add(bytes(&clip.geometry.edges)?, bytes(&clip.geometry.shapes)?)?,
176	            )?;
177	        }
178	        for pattern in &self.patterns {
179	            control
180	                .charge(WorkKind::PaintVisit, 1)
