429	    builder: &SceneBuilder,
430	    id: SceneId,
431	    value: &OpacityGroup,
432	    control: &mut dyn WorkControl,
433	) -> Result<()> {
434	    let scene = builder.scene(id)?;
435	    value.shapes.require(scene.shapes.len(), 0)?;
436	    if !value.opacity.is_finite() || !(0.0..=1.0).contains(&value.opacity) || value.blend_mode > 4 {
437	        return Err(invalid(0));
438	    }
439	    if let Some(filter) = value.filter {
440	        if scene.filter(filter).is_none() {
441	            return Err(invalid(0));
442	        }
443	    }
444	    if let Some(mask) = value.mask {
445	        if scene.mask(mask).is_none() {
446	            return Err(invalid(0));
447	        }
448	    }
449	    let mut parent = value.parent;
450	    let mut depth = 1;
451	    while let Some(id) = parent {
452	        charge(control, WorkKind::ClipChain)?;
453	        let group = scene.group(id).ok_or_else(|| invalid(0))?;
454	        if value.shapes.first < group.shapes.first || value.shapes.end() > group.shapes.end() {
455	            return Err(invalid(0));
456	        }
457	        parent = group.parent;
458	        depth += 1;
459	        if depth > 64 {
460	            return Err(limit(LimitKind::Depth));
461	        }
462	    }
463	    Ok(())
464	}
