  4	use vexel_scene::*;
  5	#[test]
  6	fn source_is_shared_once_with_animation_and_survives_worker_move() {
  7	    fn send_sync<T: Send + Sync>() {}
  8	    send_sync::<SceneGraph>();
  9	    let source = owner();
 10	    let ptr = source.as_ptr() as usize;
 11	    let anim = animation(&source);
 12	    let retained = anim.storage_bytes().unwrap();
 13	    let builder =
 14	        SceneBuilder::new(source.clone(), anim, 72, viewport(), Limits::default()).unwrap();
 15	    assert_eq!(builder.memory_stats().source_bytes, source.capacity());
 16	    assert!(builder.memory_stats().live_bytes >= retained);
 17	    assert_eq!(Arc::strong_count(&source), 3);
 18	    drop(source);
 19	    let graph = builder.freeze().unwrap();
 20	    assert_eq!(graph.generation(), 72);
 21	    assert_eq!(graph.animation().source.as_ptr(), graph.source().as_ptr());
 22	    assert_eq!(
 23	        std::thread::spawn(move || graph.source().as_ptr() as usize)
 24	            .join()
 25	            .unwrap(),
 26	        ptr
 27	    );
 28	}
