305	fn nested_capacity_and_padding_are_charged_and_released_on_rollback() {
306	    let mut b = builder();
307	    let root = b.root_id();
308	    let initial = b.memory_stats();
309	    let mark = b.mark(root).unwrap();
310	    let im = image();
311	    let image_capacity = im.pixels.rgba.capacity();
312	    let cl = clip();
313	    let clip_capacity = cl.geometry.edges.capacity() * std::mem::size_of::<Edge>()
314	        + cl.geometry.shapes.capacity() * std::mem::size_of::<ClipChild>();
315	    let pat = pattern();
316	    let pattern_capacity = pat.tile.allocated_byte_count();
317	    b.append_image(root, im, &mut Run).unwrap();
318	    b.append_clip(root, cl, &mut Run).unwrap();
319	    b.append_pattern(root, pat, &mut Run).unwrap();
320	    let full = b.memory_stats();
321	    assert!(
322	        full.live_bytes >= initial.live_bytes + image_capacity + clip_capacity + pattern_capacity
323	    );
324	    b.rollback(mark).unwrap();
325	    let after = b.memory_stats();
326	    assert_eq!(
327	        full.live_bytes - after.live_bytes,
328	        image_capacity + clip_capacity + pattern_capacity
329	    );
330	    assert_eq!(full.peak_live_bytes, after.peak_live_bytes);
331	    assert_eq!(full.total_allocated_bytes, after.total_allocated_bytes);
332	    assert!(b.scene(root).unwrap().images.is_empty());
333	    assert!(b.freeze().is_ok());
334	}
