 12	static bool size_mul(size_t left, size_t right, size_t *out)
 13	{
 14	    if (out == NULL || (right != 0U && left > SIZE_MAX / right)) {
 15	        return false;
 16	    }
 17	    *out = left * right;
 18	    return true;
 19	}
